//! The ecology's data (`shared/ecology/ecology.json`, generated by `shared/ecology/gen.mjs` into
//! `ecology.gen.rs`): the island grid, the grazing grounds and the species. Species refer to each
//! other by index in the generated table; code finds them by name ([`Data::find`]).

/// The coarse grid the ecology runs on and its longest step.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct IslandParams {
    /// Metres a cell (sampled from the face's world map).
    pub cell_m: f64,
    /// The longest step (days): a longer fast-forward is cut into steps of at most this.
    pub step_days: f64,
}

/// A ground class: the forage a cell holds when it is under both limits (the first that fits).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct GroundDef {
    pub name: &'static str,
    pub max_height_m: f64,
    pub max_slope_deg: f64,
    /// The most forage the cell holds (deer-days: one unit feeds one head for a day).
    pub max: f64,
    /// The share of a group on this ground a hunter can't take (steep crags, cover): a refuge, one
    /// of the systemic resistances to being wiped out (0 none, 1 safe).
    pub refuge: f64,
}

/// A group's size rules.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct GroupRules {
    /// A group smaller than this is gone (it died out): no floor keeps it (owner, 2026-11-11:
    /// "systemically resistant to being wiped out, not immune from it").
    pub die_below: f64,
    /// Above this a group splits in two (or stops growing at `max_groups`).
    pub cap: f64,
    /// A group smaller than this joins a group of its kind within `merge_radius_m`.
    pub merge_below: f64,
    pub merge_radius_m: f64,
    /// The most groups of the species on the island.
    pub max_groups: usize,
}

/// What a species eats.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Diet {
    /// The cells' forage, `per_head_per_day` a head.
    Graze { per_head_per_day: f64 },
    /// Other species' groups (indices into `Data::species`).
    Prey {
        species: &'static [usize],
        /// The most kills a head a day, when prey is plentiful.
        kills_per_head_per_day: f64,
        /// Holling type III: kills fall off as `N² / (N² + h²)` of the prey head `N` the hunter can
        /// find in its sense (outside refuges); with few left, the last are hard to find.
        half_saturation_head: f64,
        need_per_head_per_day: f64,
        /// The prey a hunter needs on the island per head: its island-wide bound.
        prey_per_head: f64,
        reach_m: f64,
    },
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Flee {
    pub from: &'static [usize],
    pub radius_m: f64,
}

/// A hunter's answer to scarce prey: leave for the island's biggest prey group, members leaving.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Disperse {
    pub above_hunger: f64,
    pub speed_factor: f64,
    pub leave_per_day: f64,
}

/// A hunter that senses no prey (WORK_QUEUE item 39, owner 2026-11-12: "hungry packs travel toward
/// the nearest herd"): above `toward_prey_above_hunger` it heads for the island's nearest prey group,
/// at any distance, instead of a random heading.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Roam {
    pub toward_prey_above_hunger: f64,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct SpeciesDef {
    pub name: &'static str,
    pub group: GroupRules,
    /// The start's groups: a fixed count (`start_per_km2` 0), or from the range's area.
    pub start_groups: usize,
    /// Head a km² of the species' range at the start (a grazer's range the island's grazing land,
    /// a hunter's its land; WORK_QUEUE item 46: real densities, not a fixed count); 0: `start_groups`.
    pub start_per_km2: f64,
    /// The fewest start groups from a density (a small island still has some).
    pub start_min_groups: usize,
    pub start_size: f64,
    pub breed_per_day: f64,
    pub breed_below_hunger: f64,
    pub hunger_days: f64,
    pub starve_above_hunger: f64,
    pub starve_per_day: f64,
    pub speed_m_per_day: f64,
    pub sense_radius_m: f64,
    pub diet: Diet,
    pub flee: Option<Flee>,
    pub disperse: Option<Disperse>,
    /// A hungry hunter's roaming (WORK_QUEUE item 39); None: a random heading.
    pub roam: Option<Roam>,
    /// Its individuals near players (docs/ECOLOGY.md §8); None: it stays a record.
    pub near: Option<NearDef>,
}

impl SpeciesDef {
    /// The groups a new ecology starts with on a range of `km2` (km²): `start_groups`, or the
    /// density's head over `start_size` (rounded), at least `start_min_groups`, at most the
    /// group's `max_groups`.
    pub fn start_groups_on(&self, km2: f64) -> usize {
        if self.start_per_km2 <= 0.0 {
            return self.start_groups.min(self.group.max_groups);
        }
        let n = (km2.max(0.0) * self.start_per_km2 / self.start_size).round() as usize;
        n.max(self.start_min_groups).min(self.group.max_groups)
    }
}

/// Where groups become individuals and fold back (docs/ECOLOGY.md §8).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearParams {
    /// A player within this (face-local horizontal metres) of a record makes its individuals.
    pub spawn_m: f64,
    /// They fold back into a record once no player is within this of them (> `spawn_m`).
    pub fold_m: f64,
    /// Seconds between their decisions.
    pub think_s: f64,
    /// The steepest ground (degrees, from the rise to the next column) an individual is placed on.
    pub max_slope_deg: f64,
    /// How far (face-local metres) from its record an individual's ground is searched for when the
    /// record's own place isn't the ecology's ground (water, too steep).
    pub search_m: f64,
}

/// A species' individuals near players: the owner's mockup's needs as data
/// (docs/proposals/ECOSYSTEM_MOCKUP_NOTES.md). Hunger 0 fed, 1 none; energy 1 rested.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearDef {
    /// The creature (shared/creatures/creatures.json) its individuals are, by name.
    pub creature: &'static str,
    pub hunger_per_s: f64,
    /// Energy lost a second awake.
    pub energy_per_s: f64,
    pub sleep: NearSleep,
    /// A grazer's eating; a hunter's hunting (the one its diet calls for).
    pub graze: Option<NearGraze>,
    pub hunt: Option<NearHunt>,
    /// Fleeing the species' `flee.from` (prey only).
    pub flee: Option<NearFlee>,
    pub mate: NearMate,
    /// Otherwise it keeps within this of a groupmate.
    pub company_m: f64,
    /// The farthest it wanders a walk.
    pub wander_m: f64,
    /// How it reacts when hurt (a weapon's hit; WORK_QUEUE item 35); None: it doesn't.
    pub hurt: Option<NearHurt>,
    /// How it reacts to a player it notices (WORK_QUEUE item 39); None: it doesn't.
    pub players: Option<NearPlayers>,
    /// What it does standing about (WORK_QUEUE item 39), picked by weight; empty: it just stands.
    pub idles: &'static [NearIdle],
    /// The chance a decision with nothing to do starts a walk rather than an idle (0 to 1).
    pub walk_chance: f64,
}

/// What an individual does when it notices a player (a fixed vocabulary; the data picks one).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PlayerReact {
    /// The whole group runs `run_m` from the player at `pace`, calming `calm_s` after the last
    /// notice (the deer).
    Flee,
    /// It walks off to keep the notice distance (the wolves).
    Avoid,
}

/// Noticing players (`near.players`): the distance it notices one at by the player's stance, the
/// reaction, and boldness when hungry.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearPlayers {
    pub react: PlayerReact,
    /// A player walking (or standing, between `still_below_mps` and `sprint_above_mps`).
    pub notice_m: f64,
    /// A player crouching (sneaking).
    pub crouch_m: f64,
    /// A player standing still (slower than `still_below_mps`, horizontal).
    pub still_m: f64,
    /// A player running (faster than `sprint_above_mps`).
    pub sprint_m: f64,
    pub still_below_mps: f64,
    pub sprint_above_mps: f64,
    /// How far a flight runs each decision (m) and its pace (× its walk).
    pub run_m: f64,
    pub pace: f64,
    /// Seconds after the last notice until a fleeing group calms.
    pub calm_s: f64,
    /// Hungrier than this, it notices players only within `bold_m` (a hungry pack's boldness).
    pub bold_above_hunger: f64,
    pub bold_m: f64,
}

impl NearPlayers {
    /// The distance it notices a player at, by the player's stance and its own hunger.
    pub fn notice_at(&self, crouching: bool, speed: f64, hunger: f64) -> f64 {
        let mut r = if speed > self.sprint_above_mps {
            self.sprint_m
        } else if speed < self.still_below_mps {
            self.still_m
        } else {
            self.notice_m
        };
        if crouching {
            r = r.min(self.crouch_m);
        }
        if hunger > self.bold_above_hunger {
            r = r.min(self.bold_m);
        }
        r
    }
}

/// The idle poses (a fixed vocabulary the clients draw; the data picks among them).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum IdlePose {
    Stand,
    /// Head down to the grass.
    Graze,
    /// Head up, looking about.
    LookUp,
    EarFlick,
    Sit,
    Lie,
}

impl IdlePose {
    /// Its name in the data (`"graze"`, `"lookUp"`, …).
    pub const NAMES: [&'static str; 6] = ["stand", "graze", "lookUp", "earFlick", "sit", "lie"];
    pub const ALL: [IdlePose; 6] = [
        IdlePose::Stand,
        IdlePose::Graze,
        IdlePose::LookUp,
        IdlePose::EarFlick,
        IdlePose::Sit,
        IdlePose::Lie,
    ];
    pub fn name(self) -> &'static str {
        Self::NAMES[self as usize]
    }
}

/// One idle: its pose, weight among the species' idles and seconds ([min, max]).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearIdle {
    pub pose: IdlePose,
    pub weight: f64,
    pub seconds: [f64; 2],
}

/// The idle `u` (in [0, 1)) picks among `idles` by weight; None when there are none.
pub fn pick_idle(idles: &[NearIdle], u: f64) -> Option<NearIdle> {
    let total: f64 = idles.iter().map(|i| i.weight).sum();
    if total <= 0.0 {
        return None;
    }
    let mut at = u.clamp(0.0, 1.0) * total;
    for i in idles {
        if at < i.weight {
            return Some(*i);
        }
        at -= i.weight;
    }
    idles.last().copied()
}

/// A hurt individual's reaction (`near.hurt`): flee from the striker or fight (turn on it), for
/// `seconds` at `pace` × its walk; a fighter under `flee_below_health` of its health flees.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearHurt {
    pub react: HurtReact,
    pub seconds: f64,
    pub pace: f64,
    pub flee_below_health: f64,
    /// How far a flight runs from the striker each decision (m).
    pub run_m: f64,
}

/// The reactions a hurt individual may have (a fixed vocabulary; the data picks one).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HurtReact {
    Flee,
    Fight,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearSleep {
    pub below_energy: f64,
    pub night_chance_per_s: f64,
    pub night_below_hunger: f64,
    pub gain_per_s: f64,
    pub wake_above_energy: f64,
    pub wake_above_hunger: f64,
    pub min_s: f64,
    /// Its pose asleep.
    pub pose: IdlePose,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearGraze {
    pub above_hunger: f64,
    pub full_below: f64,
    /// Hunger eaten a second.
    pub eat_per_s: f64,
    /// The island cell's forage (deer-days) eaten a second.
    pub forage_per_s: f64,
    /// The real block it eats (the only world change, near players only).
    pub block: Option<&'static str>,
    pub block_chance_per_s: f64,
    /// Its pose eating.
    pub pose: IdlePose,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearHunt {
    pub above_hunger: f64,
    pub sense_m: f64,
    /// × its walking speed while chasing.
    pub sprint: f64,
    pub reach_m: f64,
    /// A kill feeds packmates within this by `feeds_pack` of their hunger.
    pub feeds_pack_m: f64,
    pub feeds_pack: f64,
    /// Past `sense_m` and within this, it walks toward the nearest prey (an individual, or a herd's
    /// record) to bring a hunt in range (WORK_QUEUE item 39); 0: it doesn't.
    pub track_m: f64,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearFlee {
    pub radius_m: f64,
    /// × its walking speed while fleeing.
    pub pace: f64,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NearMate {
    pub below_hunger: f64,
    pub above_energy: f64,
    pub radius_m: f64,
    pub reach_m: f64,
    /// The chance of a young a try within reach.
    pub chance: f64,
    /// Hunger each parent spends on a young.
    pub cost: f64,
    /// Energy a failed try costs.
    pub tired: f64,
    /// Seconds each parent (and the young) waits after a young before mating again (BUGS.md #79).
    pub rest_s: f64,
    /// A group has at most one young every this many seconds, from when it came near.
    pub group_every_s: f64,
}

/// One ecology: the build's ([`crate::DATA`]) or a test's fixture.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Data {
    pub island: IslandParams,
    /// Forage regrowth: this share of the gap to the cell's most, a day.
    pub regrow_per_day: f64,
    pub grounds: &'static [GroundDef],
    pub near: NearParams,
    pub species: &'static [SpeciesDef],
}

impl Data {
    /// The species named `name` (`"dwell:deer"`).
    pub fn find(&self, name: &str) -> Option<usize> {
        self.species.iter().position(|s| s.name == name)
    }

    /// The ground a land cell of this height (m above sea) and slope (degrees) is (the first that
    /// fits).
    pub fn ground_for(&self, height_m: f64, slope_deg: f64) -> Option<&GroundDef> {
        self.grounds
            .iter()
            .find(|g| height_m <= g.max_height_m && slope_deg <= g.max_slope_deg)
    }

    /// The forage a land cell of this height and slope holds at most.
    pub fn grazing_for(&self, height_m: f64, slope_deg: f64) -> f64 {
        self.ground_for(height_m, slope_deg).map_or(0.0, |g| g.max)
    }

    /// The share of the kills a hunter of `diet` makes a head when it finds `prey_head` prey
    /// (Holling type III, 0 to 1); 0 for a grazer.
    pub fn catch_share(diet: Diet, prey_head: f64) -> f64 {
        match diet {
            Diet::Prey {
                half_saturation_head: h,
                ..
            } => {
                let n2 = prey_head.max(0.0).powi(2);
                if n2 + h * h > 0.0 {
                    n2 / (n2 + h * h)
                } else {
                    0.0
                }
            }
            Diet::Graze { .. } => 0.0,
        }
    }
}
